from __future__ import annotations

from typing import Any, Union

from pysnmp.proto import rfc1902

from taf.hw.pdu.device_status import DeviceStatus
from taf.hw.pdu.exceptions import BadPortNumber

from .snmp import SnmpPdu


class ATEN(SnmpPdu):
    def __init__(
        self,
        host: str,
        timeout: Union[float, int] = 30,
        snmp_user: dict[str, Any] | None = None,
        community: str = "administrator",
    ) -> None:
        """
        :param string host: IP address or domain name of the ATEN device.
        :param float timeout: Response timeout in seconds.
        :param dict snmp_user (required only for SNMPv3): User configuration for SNMPv3 with keys: userName, authKey,
                          privKey, authProtocol (SHA/MD5), privProtocol (AES/DES)
        :param community: Community string used by SNMPv1/2.
        """
        super(ATEN, self).__init__(host, timeout, snmp_user, community)

        self._version = 1
        self._key = "1.3.6.1.4.1.21317.1.3.2.2.2.2"

    @property
    def _port_setting(self):
        return {DeviceStatus.OFF: "1", DeviceStatus.ON: "2", DeviceStatus.PENDING: "3"}

    def _get_oid_value(self, value):
        return rfc1902.Integer(self._port_setting[value])

    def _build_snmp_oid(self, port):
        if port in range(1, 9):
            return f"{self._key}.{port + 1}.0"
        elif port in range(9, 25):
            return f"{self._key}.{port + 2}.0"
        else:
            raise BadPortNumber(f"Port number is invalid: {port}")
